'use strict';

const fs = require('node:fs');
const path = require('node:path');
const dataDir = path.resolve(__dirname, '../data');
const realms = JSON.parse(fs.readFileSync(path.join(dataDir, 'realms.json'), 'utf8'));
fs.writeFileSync(
  path.join(dataDir, 'realms.js'),
  '// Generated by scripts/build-realms.js; session_id: DOT-58708687\n' +
    'window.REALMS = ' + JSON.stringify(realms, null, 2) + ';\n',
  'utf8'
);
